#include "test_common.h"
#include "vmx_ept_hook_owner.h"
#include <string.h>
#define RAW_REQUIRED ((UINT64_C(1)<<6)|(UINT64_C(1)<<14)|(UINT64_C(1)<<16)|(UINT64_C(1)<<20)|(UINT64_C(1)<<25)|(UINT64_C(1)<<26))
static _Alignas(16) unsigned char graph[4096];
static _Alignas(4096) unsigned char tables[3][4096];
static VMX_EPT_BOUND_PAGE bound[3];static VMX_EPT_PHYSICAL_PAGE physical_index[3];
static VMX_EPT_HOOK_SLOT slots[1];static _Alignas(4096) uint64_t hook_pt[512];
typedef struct F{uint32_t pool,contiguous,fail_hook,free_pool,free_contiguous,poison_allocator,poison_free;VMX_PERSISTENT_ALLOCATOR*mutable_allocator;void*forced_slot;}F;
static void PoisonFreePool(void*c,void*p){(void)p;((F*)c)->poison_free++;}
static void* Pool(void*c,size_t n){F*f=(F*)c;f->pool++;if(f->pool==1)return n<=sizeof(graph)?graph:0;if(f->pool==2)return n==sizeof(bound)?bound:0;if(f->pool==3)return n==sizeof(physical_index)?physical_index:0;if(f->pool==4){if(f->poison_allocator&&f->mutable_allocator)f->mutable_allocator->FreePool=PoisonFreePool;return n==sizeof(slots)?(f->forced_slot?f->forced_slot:slots):0;}return 0;}
static void FreePool(void*c,void*p){(void)p;((F*)c)->free_pool++;}
static void* Contiguous(void*c,size_t n,uint64_t highest){F*f=(F*)c;(void)highest;f->contiguous++;if(f->contiguous==1)return n==sizeof(tables)?tables:0;if(f->contiguous==2)return !f->fail_hook&&n==sizeof(hook_pt)?hook_pt:0;return 0;}
static void FreeContiguous(void*c,void*p){(void)p;((F*)c)->free_contiguous++;}
static uint64_t Physical(void*c,const void*p){(void)c;if((uintptr_t)p>=(uintptr_t)hook_pt&&(uintptr_t)p<(uintptr_t)hook_pt+sizeof(hook_pt))return UINT64_C(0xd000)+(uintptr_t)p-(uintptr_t)hook_pt;return UINT64_C(0x9000)+(uintptr_t)p-(uintptr_t)tables;}
static VMX_PERSISTENT_ALLOCATOR Allocator(F*f){VMX_PERSISTENT_ALLOCATOR a={0};a.Context=f;a.AllocatePool=Pool;a.FreePool=FreePool;a.AllocateContiguous=Contiguous;a.FreeContiguous=FreeContiguous;a.GetPhysicalAddress=Physical;return a;}
static void Setup(F*f,VMX_EPT_SESSION_OWNER*s,VMX_EPT_HOOK_OWNER*o,VMX_PROCESSOR_IDENTITY*id){VMX_EPT_CAPABILITIES c={0};VMX_EPT_IDENTITY_CONFIG i={0};VMX_EPT_POPULATE_CONFIG p={0};VMX_PERSISTENT_ALLOCATOR a=Allocator(f);memset(f,0,sizeof(*f));memset(s,0,sizeof(*s));memset(o,0,sizeof(*o));memset(id,0,sizeof(*id));memset(graph,0,sizeof(graph));memset(tables,0,sizeof(tables));memset(bound,0,sizeof(bound));memset(physical_index,0,sizeof(physical_index));memset(slots,0,sizeof(slots));memset(hook_pt,0,sizeof(hook_pt));TEST_ASSERT_INT_EQ(VmxEptDecodeCapabilities(RAW_REQUIRED,&c),VMX_EPT_STATUS_OK,"caps");i.MappedBytes=UINT64_C(0x200000);i.PhysicalAddressBits=48;i.LeafKind=VMX_EPT_ENTRY_LEAF_2MB;p.Permissions=VMX_EPT_PERMISSION_MASK;p.MemoryType=VMX_EPT_MEMORY_TYPE_WB;TEST_ASSERT_INT_EQ(VmxEptSessionOwnerInitialize(&c,&i,&p,id,1,&a,s),VMX_EPT_SESSION_OK,"session");TEST_ASSERT_INT_EQ(VmxEptRootCoordinatorPrepareEnter(s->Root,0),VMX_EPT_ROOT_OK,"enter prepare");TEST_ASSERT_INT_EQ(VmxEptRootCoordinatorCompleteEnter(s->Root,0),VMX_EPT_ROOT_OK,"enter complete");TEST_ASSERT_INT_EQ(VmxEptCoverageMarkUse(s->Coverage,0),VMX_EPT_COVERAGE_OK,"mark use");}
static void Invalidate(VMX_EPT_SESSION_OWNER*s){VMX_EPT_INVALIDATION_REQUEST q;VMX_EPT_INVALIDATION_DESCRIPTOR d;VMX_EPT_EXECUTION_REPORT r={0};TEST_ASSERT_INT_EQ(VmxEptCoverageBuildInvalidation(s->Coverage,&q,&d),VMX_EPT_COVERAGE_OK,"build invalidation");r.Type=VMX_EPT_INVALIDATION_SINGLE_CONTEXT;r.CurrentIrql=VMX_EPT_EXECUTION_MAX_IRQL;r.Attempted=1;r.InstructionResult=VMX_EPT_INSTRUCTION_SUCCESS;r.EptPointer=s->Storage->Domain.EptPointer;TEST_ASSERT_INT_EQ(VmxEptCoverageAcceptReport(s->Coverage,0,&r),VMX_EPT_COVERAGE_OK,"accept invalidation");}
static void Finish(F*f,VMX_EPT_SESSION_OWNER*s,VMX_EPT_HOOK_OWNER*o){TEST_ASSERT_INT_EQ(VmxEptHookOwnerDestroy(o),VMX_EPT_HOOK_OWNER_OK,"owner destroy");TEST_ASSERT_INT_EQ(VmxEptCoveragePrepareRelease(s->Coverage,0),VMX_EPT_COVERAGE_OK,"release prepare");TEST_ASSERT_INT_EQ(VmxEptCoverageCompleteRelease(s->Coverage,0),VMX_EPT_COVERAGE_OK,"release complete");TEST_ASSERT_INT_EQ(VmxEptSessionOwnerDestroy(s),VMX_EPT_SESSION_OK,"session destroy");TEST_ASSERT_UINT_EQ(f->free_pool,4,"pool frees");}
static int test_transaction(void){F f;VMX_EPT_SESSION_OWNER s;VMX_EPT_HOOK_OWNER o;VMX_PROCESSOR_IDENTITY id;VMX_PERSISTENT_ALLOCATOR a;uint32_t hook,unhook;Setup(&f,&s,&o,&id);Invalidate(&s);a=Allocator(&f);TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&a,&o),VMX_EPT_HOOK_OWNER_OK,"owner");TEST_ASSERT_INT_EQ(VmxEptHookOwnerPrepare(&o,UINT64_C(0x12000),VMX_EPT_PERMISSION_WRITE,&hook),VMX_EPT_HOOK_OWNER_OK,"prepare");TEST_ASSERT_UINT_EQ(hook,0,"id");TEST_ASSERT_UINT_EQ(((uint64_t*)tables[2])[0],o.Slots[0].Record.Plan.ReplacementParentEntry,"parent published");TEST_ASSERT_INT_EQ(VmxEptHookOwnerCommit(&o,hook),VMX_EPT_HOOK_OWNER_DIRTY,"commit waits");Invalidate(&s);TEST_ASSERT_INT_EQ(VmxEptHookOwnerCommit(&o,hook),VMX_EPT_HOOK_OWNER_OK,"commit");TEST_ASSERT_INT_EQ(VmxEptHookOwnerBeginUnhook(&o,UINT64_C(0x12000),&unhook),VMX_EPT_HOOK_OWNER_OK,"unhook begin");TEST_ASSERT_UINT_EQ(((uint64_t*)tables[2])[0],o.Slots[0].Record.Plan.OriginalParentEntry,"parent restored");Invalidate(&s);TEST_ASSERT_INT_EQ(VmxEptHookOwnerCompleteUnhook(&o,unhook),VMX_EPT_HOOK_OWNER_OK,"unhook complete");TEST_ASSERT_UINT_EQ(o.ActiveCount,0,"active zero");Finish(&f,&s,&o);TEST_ASSERT_UINT_EQ(f.free_contiguous,2,"table and hook pages freed");return 0;}
static int test_failures(void){F f;VMX_EPT_SESSION_OWNER s;VMX_EPT_HOOK_OWNER o;VMX_PROCESSOR_IDENTITY id;VMX_PERSISTENT_ALLOCATOR a;uint32_t id_out,query_id,query_stage;uint64_t query_gpa;Setup(&f,&s,&o,&id);Invalidate(&s);a=Allocator(&f);TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&a,&o),VMX_EPT_HOOK_OWNER_OK,"owner");query_id=77;query_stage=88;TEST_ASSERT_INT_EQ(VmxEptHookOwnerQuery(&o,0,&query_id,&query_stage),VMX_EPT_HOOK_OWNER_NOT_FOUND,"query missing");TEST_ASSERT_UINT_EQ(query_id,77,"query id preserved");TEST_ASSERT_UINT_EQ(query_stage,88,"query stage preserved");f.fail_hook=1;TEST_ASSERT_INT_EQ(VmxEptHookOwnerPrepare(&o,0,VMX_EPT_PERMISSION_READ,&id_out),VMX_EPT_HOOK_OWNER_ALLOCATION_FAILED,"allocation");TEST_ASSERT_UINT_EQ(o.ActiveCount,0,"no publication");f.fail_hook=0;TEST_ASSERT_INT_EQ(VmxEptHookOwnerPrepare(&o,0,VMX_EPT_PERMISSION_READ,&id_out),VMX_EPT_HOOK_OWNER_OK,"prepare");TEST_ASSERT_INT_EQ(VmxEptHookOwnerQuery(&o,0,&query_id,&query_stage),VMX_EPT_HOOK_OWNER_OK,"query prepared");TEST_ASSERT_UINT_EQ(query_id,id_out,"query id");TEST_ASSERT_UINT_EQ(query_stage,VMX_EPT_HOOK_STAGE_PREPARED,"query stage");TEST_ASSERT_INT_EQ(VmxEptHookOwnerQueryFirst(&o,&query_gpa,&query_id,&query_stage),VMX_EPT_HOOK_OWNER_OK,"query first");TEST_ASSERT_UINT_EQ(query_gpa,0,"query first gpa");TEST_ASSERT_INT_EQ(VmxEptHookOwnerDestroy(&o),VMX_EPT_HOOK_OWNER_BUSY,"active blocks destroy");Invalidate(&s);TEST_ASSERT_INT_EQ(VmxEptHookOwnerCommit(&o,id_out),VMX_EPT_HOOK_OWNER_OK,"commit");TEST_ASSERT_INT_EQ(VmxEptHookOwnerPrepare(&o,0,VMX_EPT_PERMISSION_WRITE,&id_out),VMX_EPT_HOOK_OWNER_BUSY,"duplicate");TEST_ASSERT_INT_EQ(VmxEptHookOwnerBeginUnhook(&o,UINT64_C(0x1000),&id_out),VMX_EPT_HOOK_OWNER_NOT_FOUND,"not found");TEST_ASSERT_INT_EQ(VmxEptHookOwnerBeginUnhook(&o,0,&id_out),VMX_EPT_HOOK_OWNER_OK,"begin");Invalidate(&s);TEST_ASSERT_INT_EQ(VmxEptHookOwnerCompleteUnhook(&o,id_out),VMX_EPT_HOOK_OWNER_OK,"complete");TEST_ASSERT_INT_EQ(VmxEptHookOwnerQueryFirst(&o,&query_gpa,&query_id,&query_stage),VMX_EPT_HOOK_OWNER_NOT_FOUND,"query empty");Finish(&f,&s,&o);return 0;}
static int test_initialize_admission_and_allocator_snapshot(void){typedef union ALIAS{VMX_PERSISTENT_ALLOCATOR Allocator;VMX_EPT_HOOK_OWNER Owner;}ALIAS;F f;VMX_EPT_SESSION_OWNER s;VMX_EPT_HOOK_OWNER o;VMX_PROCESSOR_IDENTITY id;VMX_PERSISTENT_ALLOCATOR a;ALIAS alias,before;unsigned char graph_before[sizeof(graph)];Setup(&f,&s,&o,&id);TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&s.Allocator,&o),VMX_EPT_HOOK_OWNER_OK,"canonical embedded allocator admitted");Finish(&f,&s,&o);Setup(&f,&s,&o,&id);a=Allocator(&f);f.poison_allocator=1;f.mutable_allocator=&a;f.forced_slot=&o;TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&a,&o),VMX_EPT_HOOK_OWNER_INVARIANT,"allocator mutation unwind");TEST_ASSERT_UINT_EQ(f.free_pool,1,"frozen allocator cleanup");TEST_ASSERT_UINT_EQ(f.poison_free,0,"poison cleanup rejected");TEST_ASSERT_TRUE(memcmp(&o,&(VMX_EPT_HOOK_OWNER){0},sizeof(o))==0,"failed initialization preserves owner");Finish(&f,&s,&o);Setup(&f,&s,&o,&id);a=Allocator(&f);memcpy(graph_before,graph,sizeof(graph));TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&a,(VMX_EPT_HOOK_OWNER*)s.Graph),VMX_EPT_HOOK_OWNER_INVALID,"session graph output overlap rejected");TEST_ASSERT_TRUE(memcmp(graph,graph_before,sizeof(graph))==0,"session graph overlap preserves storage");memset(&alias,0,sizeof(alias));alias.Allocator=Allocator(&f);before=alias;TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&alias.Allocator,&alias.Owner),VMX_EPT_HOOK_OWNER_INVALID,"allocator and owner overlap rejected");TEST_ASSERT_TRUE(memcmp(&alias,&before,sizeof(alias))==0,"overlap preserves caller storage");a=Allocator(&f);TEST_ASSERT_INT_EQ(VmxEptHookOwnerInitialize(&s,1,&a,&o),VMX_EPT_HOOK_OWNER_OK,"valid owner after overlap rejection");Finish(&f,&s,&o);return 0;}
int main(void){TEST_RUN(test_transaction);TEST_RUN(test_failures);TEST_RUN(test_initialize_admission_and_allocator_snapshot);return 0;}
